metadata.vithanco:vgl:
vgraph vithancoOverviewNotations: ConceptMap "Vithanco Overview" {
    node graphN: Concept "Graph";
    node notation: Concept "Notation";
    node nodeTypes: Concept "Node Type(s)";
    node visRep: Concept "Visual Representation";
    node clusters: Concept "Group(s)";
    node nodesN: Concept "Node(s)";
    node edgesN: Concept "Edge(s)";

    node rGuides: Relation "creation and manipulation is guided by";
    node rContains: Relation "contains";
    node rDefinesValid: Relation "defines valid";
    node rDefines: Relation "defines";
    node rConsists: Relation "consists of";
    node rCanHave: Relation "can have";
    node rGroups: Relation "groups";
    node rConnects: Relation "connects two";
    node rUsedBy: Relation "used by";

    edge graphN -> rGuides;
    edge rGuides -> notation;
    edge notation -> rContains;
    edge rContains -> nodeTypes;
    edge notation -> rDefinesValid;
    edge rDefinesValid -> edgesN;
    edge nodeTypes -> rDefines;
    edge rDefines -> nodesN;
    edge visRep -> rConsists;
    edge rConsists -> nodesN;
    edge visRep -> rCanHave;
    edge rCanHave -> clusters;
    edge clusters -> rGroups;
    edge rGroups -> nodesN;
    edge edgesN -> rConnects;
    edge rConnects -> nodesN;
    edge edgesN -> rUsedBy;
    edge rUsedBy -> visRep;
}
